    { alvo: '[data-t=tabela-publicos]', fim: true, semVolta: true, garante: function () { var s = pb().S; if (!s.auds.length) { s.auds.push(aud('Brasil 18+', 'Público salvo', '—', 0, 'Brasil · idade mínima 18')) } SIMPB.abre(null) }, tit: T('Público salvo! 🎉', '¡Público guardado! 🎉'), txt: T('O público salvo entra na lista e pode ser reutilizado em outros anúncios. Clique em Concluir. Depois, explore à vontade: o botão ↩ no canto leva de volta.', 'El público guardado entra en la lista y se puede reutilizar en otros anuncios. Haz clic en Terminar. Después, explora a gusto: el botón ↩ en la esquina te lleva de vuelta.') }
